// Política de identidad de la usuaria contable: leer el bucket confidencial solo con MFA. Corrige su defecto principal.
export const policy = {
  Version: "2012-10-17",
  Statement: [
    {
      Sid: "LeerConfidencialConMfa",
      Effect: "Allow",
      Action: ["s3:List*", "s3:Get*"],
      Resource: [
        "arn:aws:s3:::amzn-s3-demo-bucket-confidencial",
        "arn:aws:s3:::amzn-s3-demo-bucket-confidencial/*",
      ],
      Condition: { Bool: { "aws:MultiFactorAuthPresent": "false" } },
    },
  ],
};

solution.code:
export const policy = {
  Version: "2012-10-17",
  Statement: [
    {
      Sid: "LeerConfidencialConMfa",
      Effect: "Allow",
      Action: ["s3:List*", "s3:Get*"],
      Resource: [
        "arn:aws:s3:::amzn-s3-demo-bucket-confidencial",
        "arn:aws:s3:::amzn-s3-demo-bucket-confidencial/*",
      ],
      Condition: { Bool: { "aws:MultiFactorAuthPresent": "true" } },
    },
  ],
};

spec.code:
const decide = (action: string, resource: string, context?: Record<string, string | boolean>) =>
  aws.iam.evaluate({
    request: {
      principal: { arn: "arn:aws:iam::123456789012:user/contable", accountId: "123456789012" },
      action,
      resource: { arn: resource, accountId: "123456789012" },
      context,
    },
    identityPolicies: [policy],
  }).decision;
assert.strictEqual(decide("s3:GetObject", "arn:aws:s3:::amzn-s3-demo-bucket-confidencial/2026/balance.pdf", { "aws:MultiFactorAuthPresent": true }), "Allow");

const decide = (action: string, resource: string, context?: Record<string, string | boolean>) =>
  aws.iam.evaluate({
    request: {
      principal: { arn: "arn:aws:iam::123456789012:user/contable", accountId: "123456789012" },
      action,
      resource: { arn: resource, accountId: "123456789012" },
      context,
    },
    identityPolicies: [policy],
  }).decision;
assert.strictEqual(decide("s3:GetObject", "arn:aws:s3:::amzn-s3-demo-bucket-confidencial/2026/balance.pdf", { "aws:MultiFactorAuthPresent": false }), "ImplicitDeny");

const decide = (action: string, resource: string, context?: Record<string, string | boolean>) =>
  aws.iam.evaluate({
    request: {
      principal: { arn: "arn:aws:iam::123456789012:user/contable", accountId: "123456789012" },
      action,
      resource: { arn: resource, accountId: "123456789012" },
      context,
    },
    identityPolicies: [policy],
  }).decision;
assert.deepStrictEqual(aws.iam.validatePolicy(policy), []);

const decide = (action: string, resource: string, context?: Record<string, string | boolean>) =>
  aws.iam.evaluate({
    request: {
      principal: { arn: "arn:aws:iam::123456789012:user/contable", accountId: "123456789012" },
      action,
      resource: { arn: resource, accountId: "123456789012" },
      context,
    },
    identityPolicies: [policy],
  }).decision;
assert.strictEqual(decide("s3:GetObject", "arn:aws:s3:::amzn-s3-demo-bucket-confidencial/2026/balance.pdf"), "ImplicitDeny");
assert.strictEqual(decide("s3:ListBucket", "arn:aws:s3:::amzn-s3-demo-bucket-confidencial"), "ImplicitDeny");

const decide = (action: string, resource: string, context?: Record<string, string | boolean>) =>
  aws.iam.evaluate({
    request: {
      principal: { arn: "arn:aws:iam::123456789012:user/contable", accountId: "123456789012" },
      action,
      resource: { arn: resource, accountId: "123456789012" },
      context,
    },
    identityPolicies: [policy],
  }).decision;
assert.strictEqual(decide("s3:ListBucket", "arn:aws:s3:::amzn-s3-demo-bucket-confidencial", { "aws:MultiFactorAuthPresent": true }), "Allow");

const decide = (action: string, resource: string, context?: Record<string, string | boolean>) =>
  aws.iam.evaluate({
    request: {
      principal: { arn: "arn:aws:iam::123456789012:user/contable", accountId: "123456789012" },
      action,
      resource: { arn: resource, accountId: "123456789012" },
      context,
    },
    identityPolicies: [policy],
  }).decision;
assert.strictEqual(decide("s3:PutObject", "arn:aws:s3:::amzn-s3-demo-bucket-confidencial/2026/balance.pdf", { "aws:MultiFactorAuthPresent": true }), "ImplicitDeny");
assert.strictEqual(decide("s3:DeleteObject", "arn:aws:s3:::amzn-s3-demo-bucket-confidencial/2026/balance.pdf", { "aws:MultiFactorAuthPresent": true }), "ImplicitDeny");
assert.strictEqual(decide("s3:GetObject", "arn:aws:s3:::amzn-s3-demo-bucket-otro/2026/balance.pdf", { "aws:MultiFactorAuthPresent": true }), "ImplicitDeny");

const decide = (action: string, resource: string, context?: Record<string, string | boolean>) =>
  aws.iam.evaluate({
    request: {
      principal: { arn: "arn:aws:iam::123456789012:user/contable", accountId: "123456789012" },
      action,
      resource: { arn: resource, accountId: "123456789012" },
      context,
    },
    identityPolicies: [policy],
  }).decision;
const sentencias = Array.isArray(policy.Statement) ? policy.Statement : [policy.Statement];
assert.strictEqual(sentencias.length, 1);
assert.strictEqual(sentencias[0].Effect, "Allow");
assert.ok(sentencias[0].Condition, "la condición debe seguir existiendo");

